for (const it of items) {
  for (const p of (it.json.projects || [])) {
    out.push({ json: { project_id: p.project_id, project_name: p.name } });
  }
}
return out;

const CUTOFF = 1791410400; // 2026-10-08 00:00 Europe/Warsaw
const TAG = '081026';
const projs = $('Split Projects').all();
const names = {};
for (const p of projs) { names[p.json.project_id] = p.json.project_name; }
const res = $input.all();
const byProj = {};
const errors = [];
function nm(k) { const n = k.key_name; if (!n) return ''; if (typeof n === 'string') return n; return n.web || n.ios || n.android || n.other || Object.values(n)[0] || ''; }
for (let i = 0; i < res.length; i++) {
  const body = res[i].json || {};
  if (!body.keys) { errors.push(JSON.stringify(body).slice(0, 300)); continue; }
  const pid = body.project_id;
  if (!byProj[pid]) byProj[pid] = { project_id: pid, project_name: names[pid] || pid, scanned: 0, pages: 0, created: 0, key_modified: 0, tr_modified: 0, already_tagged: 0, archived_skipped: 0, key_ids: [], sample: [] };
  const b = byProj[pid];
  b.pages++;
  for (const k of body.keys) {
    b.scanned++;
    const c = (k.created_at_timestamp || 0) >= CUTOFF;
    const m = (k.modified_at_timestamp || 0) >= CUTOFF;
    const t = (k.translations_modified_at_timestamp || 0) >= CUTOFF;
    if (!(c || m || t)) continue;
    if (k.is_archived) { b.archived_skipped++; continue; }
    if (c) b.created++; else if (t) b.tr_modified++; else b.key_modified++;
    if ((k.tags || []).indexOf(TAG) >= 0) { b.already_tagged++; continue; }
    b.key_ids.push(k.key_id);
    if (b.sample.length < 5) b.sample.push(nm(k));
  }
}
const missing = [];
for (const p of projs) { if (!byProj[p.json.project_id]) missing.push(p.json.project_name); }
const rows = Object.values(byProj).filter(function (b) { return b.created + b.key_modified + b.tr_modified > 0; });
let total = 0; let scanned = 0;
for (const b of Object.values(byProj)) { scanned += b.scanned; }
for (const r of rows) { total += r.key_ids.length; }
return [{ json: { projects_total: projs.length, projects_scanned: Object.keys(byProj).length, keys_scanned: scanned, to_tag_total: total, missing_projects: missing, errors: errors.slice(0, 10), page_counts: Object.values(byProj).map(function (b) { return b.project_name + ':' + b.pages + '/' + b.scanned; }), rows: rows.map(function (r) { return { project_id: r.project_id, project_name: r.project_name, created: r.created, key_modified: r.key_modified, tr_modified: r.tr_modified, already_tagged: r.already_tagged, archived_skipped: r.archived_skipped, to_tag: r.key_ids.length, sample: r.sample, key_ids: r.key_ids }; }) } }];
